package com.stark.automation.ui.tests;
import com.stark.automation.base.UiBaseTest; import com.stark.automation.config.ConfigurationManager; import com.stark.automation.listeners.RetryAnalyzer; import com.stark.automation.pages.InventoryPage; import com.stark.automation.pages.LoginPage; import org.testng.Assert; import org.testng.annotations.Listeners; import org.testng.annotations.Test;
@Listeners(com.stark.automation.listeners.TestListener.class) public class ShoppingTests extends UiBaseTest { private InventoryPage signIn() { return new LoginPage().open(ConfigurationManager.value("base.url")).loginAs("standard_user", "secret_sauce"); } @Test(retryAnalyzer = RetryAnalyzer.class) public void userCanAddProductToCart() { Assert.assertEquals(signIn().addBackpack().cartCount(), "1", "Cart badge should show one product"); } @Test(retryAnalyzer = RetryAnalyzer.class) public void cartShowsChosenProduct() { Assert.assertEquals(signIn().addBackpack().openCart().itemName(), "Sauce Labs Backpack"); } @Test(retryAnalyzer = RetryAnalyzer.class) public void checkoutRequiresCustomerDetails() { Assert.assertTrue(signIn().addBackpack().openCart().checkout().continueWithoutDetails().errorMessage().contains("First Name is required")); } @Test(retryAnalyzer = RetryAnalyzer.class) public void userCanLogOut() { new LoginPage().open(ConfigurationManager.value("base.url")).loginAs("standard_user", "secret_sauce").logout(); Assert.assertTrue(com.stark.automation.core.driver.DriverFactory.getDriver().getCurrentUrl().contains("saucedemo.com")); } }
